+import { createServer } from "http";
+import { claimNext, completeJob, failJob } from "./jobs.ts";
+
+const PORT = process.env.PORT ? parseInt(process.env.PORT) : 3000;
+
+const parseJsonBody = async (req: any): Promise<any> => {
+  return new Promise((resolve, reject) => {
+    let data = "";
+    req.on("data", (chunk: string) => {
+      data += chunk;
+    });
+    req.on("end", () => {
+      try {
+        resolve(data ? JSON.parse(data) : {});
+      } catch (e) {
+        reject(new Error("Invalid JSON"));
+      }
+    });
+  });
+};
+
+export const createJobServer = (): void => {
+  const server = createServer(async (req, res) => {
+    res.setHeader("Content-Type", "application/json");
+
+    try {
+      if (req.method === "GET" && req.url === "/api/jobs/claim") {
+        const job = await claimNext();
+        if (job === null) {
+          res.writeHead(204);
+          res.end();
+          return;
+        }
+        res.writeHead(200);
+        res.end(JSON.stringify(job));
+        return;
+      }
+
+      if (req.method === "POST" && req.url?.startsWith("/api/jobs/")) {
+        const parts = req.url.split("/");
+        const jobId = parts[3];
+        const action = parts[4];
+
+        if (!jobId) {
+          res.writeHead(400);
+          res.end(JSON.stringify({ error: "Job ID is required" }));
+          return;
+        }
+
+        if (action === "complete") {
+          await completeJob(jobId);
+          res.writeHead(200);
+          res.end(JSON.stringify({ status: "completed" }));
+          return;
+        }
+
+        if (action === "fail") {
+          const body = await parseJsonBody(req);
+          await failJob(jobId, body.reason);
+          res.writeHead(200);
+          res.end(JSON.stringify({ status: "failed" }));
+          return;
+        }
+      }
+
+      res.writeHead(404);
+      res.end(JSON.stringify({ error: "Not found" }));
+    } catch (error) {
+      res.writeHead(500);
+      res.end(JSON.stringify({ error: "Internal server error" }));
+    }
+  });
+
+  server.listen(PORT, () => {
+    console.log(`Job server listening on http://localhost:${PORT}`);
+  });
+};
